WITH base AS (SELECT id, customer_id, order_date, status, channel, amount, discount, shipping_fee, DATEDIFF(CURRENT_DATE(), order_date) AS days_since_order_date, discount - shipping_fee AS discount_minus_shipping_fee, COALESCE(channel, 'UNKNOWN') AS channel_clean FROM orders WHERE channel IS NOT NULL), matched AS (SELECT e.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM base e LEFT JOIN promotions pr ON e.channel = pr.channel AND e.order_date >= pr.starts_on AND e.order_date <= DATE_ADD(pr.ends_on, 10)), deduped AS (SELECT * FROM matched QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id, channel ORDER BY shipping_fee DESC NULLS LAST, id, promo_id) = 1), scored AS (SELECT *, CUME_DIST() OVER (PARTITION BY status, channel ORDER BY days_since_order_date DESC NULLS FIRST) AS days_since_order_date_cume_dist, CUME_DIST() OVER (PARTITION BY status, channel ORDER BY promo_id NULLS FIRST) AS promo_id_cume_dist, DENSE_RANK() OVER (PARTITION BY promo_code ORDER BY days_since_order_date DESC NULLS FIRST) AS days_since_order_date_dense_rank FROM deduped) SELECT s.id, s.customer_id, s.order_date, s.status, s.channel, s.discount, s.shipping_fee, s.days_since_order_date, s.discount_minus_shipping_fee, (SELECT SUM(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS sum_account_balance FROM scored s ORDER BY sum_account_balance
